777	// ---------------------------------------------------------------------------
778	// 请求记录（默认仅在进程内；serve --requests-file 时持久化到本地记录文件）
779	// ---------------------------------------------------------------------------
780	//
781	// 仅记录管理范围之外、完整接收且未超过正文上限的请求（场景响应、400、404）。
782	// 未收完整即断开或超出上限不创建记录、不消费序列。
783	// 编号按“完整接收”顺序单调递增，与接口消费位置是两回事；清空与成功/失败重载
784	// 都保留编号序列，编号不复用——持久模式下编号进度（nextId）单独保存在记录库中，
785	// 清空后重启也不能依据剩余记录的最大编号续号。
786	//
787	// 持久模式（--requests-file）：
788	// - 文件不存在时建立空记录库；存在时在监听前完整恢复。恢复保留原编号、接收顺序、
789	//   原始请求头、无损正文、接收时版本、校验与分支结论、消费位置及计划响应，
790	//   不按当前配置重判；恢复不重发历史请求或响应，不恢复业务序列与配置版本。
791	// - 落盘为整库原子替换（同目录临时文件 + rename）；新增、状态更新与清空交错时
792	//   按调用顺序串行落盘，每次写出落盘时刻的最新整库，较晚的保存不会用旧状态覆盖。
793	// - 恢复时上次未确认完成（pending）的记录一律标记为 interrupted：该状态只表示
794	//   服务器未确认完成写出，不能证明客户端未收到响应；已确认的 sent 不回退。
795	
796	// 写出生命周期（仅指服务器侧写出，不表示客户端已收到）：
797	//   pending     —— 已完整接收、计划响应待发送（延迟期间即可查到）
798	//   sent        —— 服务器已完成响应写出；此后连接正常关闭不再改变状态
799	//   interrupted —— 写出完成前连接断开或写入/发送失败；持久记录跨进程恢复时，
800	//                  上次未确认完成的 pending 也归此状态（不代表客户端未收到）
801	type DeliveryStatus = 'pending' | 'sent' | 'interrupted';
802	
803	// 计划响应：场景响应为 'scene'，400/404 等框架响应为 'framework'
804	interface PlannedResponseSnapshot {
805	  readonly kind: 'scene' | 'framework';
806	  readonly status: number;
807	  // 应用层响应头：配置头/框架头 + 服务器填写的准确版本头，不含传输层自动头
808	  readonly headers: { readonly [name: string]: string };
809	  // 配置/框架给出的响应正文文本（不含 HTTP 层按 Content-Length 等补出的字节）
810	  readonly body: string;
811	}
812	
813	interface RequestRecord {
814	  readonly id: number;
815	  readonly receivedAt: string;
816	  readonly request: {
817	    readonly method: string;
818	    // 含查询串的原始请求目标
819	    readonly target: string;
820	    readonly path: string;
821	    // 原始请求头：按在线顺序成对保留，名称大小写与重复头均不折叠
822	    readonly rawHeaders: readonly string[];
823	    readonly bodyBytes: number;
824	    // 正文原始字节的无损表示：合法 UTF-8 时以文本给出，否则以 base64 给出
825	    readonly body: { readonly encoding: 'utf-8' | 'base64'; readonly content: string };
826	  };
827	  // 完整接收那一刻选用的配置版本；在途请求的结论不随之后的 reload 改变
828	  configVersion: number;
829	  // matched=false：未匹配（404），不消费任何序列
830	  matched: boolean;
831	  endpoint: string | null;
832	  // null 表示未做正文校验（GET/未声明规则）；true=通过，false=拒绝并返回 400
833	  bodyValidationPassed: boolean | null;
834	  // 400 时实际返回的差异报告（与响应正文中的 JSON 同一份数据）
835	  bodyRejection: BodyReport | null;
836	  // 场景请求的分支选择：
837	  //   null                 —— 未选择（400/404，或无分支的场景请求之外的情形）；
838	  //   { kind:'fallback' }  —— 无分支命中，使用接口兜底 responses；
839	  //   { kind:'branch', id }—— 命中指定分支，使用该支 responses。
840	  // 无分支接口的场景请求记为 fallback。
841	  branchSelection: { readonly kind: 'branch'; readonly id: string } | { readonly kind: 'fallback' } | null;
842	  // 场景请求在“选中序列”中的消费位置（0 起）；400/404 没有消费位置，记为 null
843	  sequencePosition: number | null;
844	  // 选中序列（命中分支或兜底）的长度；400/404 为 null
845	  sequenceLength: number | null;
846	  plannedResponse: PlannedResponseSnapshot | null;
847	  delivery: DeliveryStatus;
848	}
849	
850	// ---------------------------------------------------------------------------
851	// 持久记录文件：格式、监听前恢复校验、原子落盘
852	// ---------------------------------------------------------------------------
853	
854	const REQUEST_STORE_FORMAT = 'contractlab-request-log-1';
855	const REQUEST_STORE_VERSION = 1;
856	
857	class RequestStoreError extends Error {
858	  constructor(message: string) {
859	    super(message);
860	    this.name = 'RequestStoreError';
861	  }
862	}
863	
864	function storeFail(file: string, where: string, message: string): never {
865	  const prefix = `请求记录文件 ${file} 恢复校验失败`;
866	  throw new RequestStoreError(where === '' ? `${prefix}：${message}` : `${prefix}：${where} ${message}`);
867	}
868	
869	// 校验一对恢复出的响应头：名称为合法 token、值不含非法控制字符且仅 Latin-1
870	function validateStoredHeader(name: unknown, value: unknown, file: string, where: string): void {
871	  if (typeof name !== 'string' || !HEADER_NAME_RE.test(name)) {
872	    storeFail(file, where, `头名称必须是合法 HTTP token，收到 ${JSON.stringify(name)}`);
873	  }
874	  if (typeof value !== 'string') {
875	    storeFail(file, where, `头 ${JSON.stringify(name)} 的值必须是字符串`);
876	  }
877	  for (let i = 0; i < (value as string).length; i += 1) {
878	    const code = (value as string).charCodeAt(i);
879	    if ((code <= 0x1f && code !== 0x09) || code === 0x7f || code > 0xff) {
880	      storeFail(file, where, `头 ${JSON.stringify(name)} 的值含换行/控制字符或非 Latin-1 字符`);
881	    }
882	  }
883	}
884	
885	// 严格校验单条恢复记录；任何字段缺失、类型错误、不一致或正文无法无损还原都拒绝。
886	// 返回可直接作为 RequestRecord 使用的对象（不按当前配置重判任何结论）。
887	function validateStoredRecord(raw: unknown, index: number, file: string): RequestRecord {
888	  const where = `records[${index}]`;
889	  if (!isPlainObject(raw)) {
890	    storeFail(file, where, '必须是对象');
891	  }
892	  const rec = raw as Record<string, unknown>;
893	  for (const key of Object.keys(rec)) {
894	    if (
895	      key !== 'id' &&
896	      key !== 'receivedAt' &&
897	      key !== 'request' &&
898	      key !== 'configVersion' &&
899	      key !== 'matched' &&
900	      key !== 'endpoint' &&
901	      key !== 'bodyValidationPassed' &&
902	      key !== 'bodyRejection' &&
903	      key !== 'branchSelection' &&
904	      key !== 'sequencePosition' &&
905	      key !== 'sequenceLength' &&
906	      key !== 'plannedResponse' &&
907	      key !== 'delivery'
908	    ) {
909	      storeFail(file, `${where}`, `含未知字段 "${key}"`);
910	    }
911	  }
912	
913	  if (!Number.isInteger(rec.id) || (rec.id as number) < 1) {
914	    storeFail(file, `${where}.id`, `必须是正整数，收到 ${JSON.stringify(rec.id)}`);
915	  }
916	  if (typeof rec.receivedAt !== 'string' || rec.receivedAt === '') {
917	    storeFail(file, `${where}.receivedAt`, '必须是非空字符串（ISO 8601 时刻）');
918	  }
919	  if (!Number.isInteger(rec.configVersion) || (rec.configVersion as number) < 1) {
920	    storeFail(file, `${where}.configVersion`, `必须是正整数，收到 ${JSON.stringify(rec.configVersion)}`);
921	  }
922	  if (typeof rec.matched !== 'boolean') {
923	    storeFail(file, `${where}.matched`, '必须是布尔值');
924	  }
925	  if (rec.endpoint !== null && typeof rec.endpoint !== 'string') {
926	    storeFail(file, `${where}.endpoint`, '必须是字符串或 null');
927	  }
928	  if (rec.bodyValidationPassed !== null && typeof rec.bodyValidationPassed !== 'boolean') {
929	    storeFail(file, `${where}.bodyValidationPassed`, '必须是布尔值或 null');
930	  }
931	  if (rec.sequencePosition !== null && (!Number.isInteger(rec.sequencePosition) || (rec.sequencePosition as number) < 0)) {
932	    storeFail(file, `${where}.sequencePosition`, '必须是非负整数或 null');
933	  }
934	  if (rec.sequenceLength !== null && (!Number.isInteger(rec.sequenceLength) || (rec.sequenceLength as number) < 1)) {
935	    storeFail(file, `${where}.sequenceLength`, '必须是正整数或 null');
936	  }
937	  if (
938	    (rec.sequencePosition === null) !== (rec.sequenceLength === null) ||
939	    (rec.sequencePosition !== null && (rec.sequencePosition as number) >= (rec.sequenceLength as number))
940	  ) {
941	    storeFail(
942	      file,
943	      where,
944	      'sequencePosition 与 sequenceLength 必须同时为 null，或满足 0 <= position < length',
945	    );
946	  }
947	  if (rec.delivery !== 'pending' && rec.delivery !== 'sent' && rec.delivery !== 'interrupted') {
948	    storeFail(
949	      file,
950	      `${where}.delivery`,
951	      `必须是 "pending" / "sent" / "interrupted" 之一，收到 ${JSON.stringify(rec.delivery)}`,
952	    );
953	  }
954	
955	  // request：与 verify/replay 快照同一套无损重建要求
956	  const reqWhere = `${where}.request`;
957	  if (!isPlainObject(rec.request)) {
958	    storeFail(file, reqWhere, '必须是对象');
959	  }
960	  const req = rec.request as Record<string, unknown>;
961	  for (const key of Object.keys(req)) {
962	    if (key !== 'method' && key !== 'target' && key !== 'path' && key !== 'rawHeaders' && key !== 'bodyBytes' && key !== 'body') {
963	      storeFail(file, reqWhere, `含未知字段 "${key}"`);
964	    }
965	  }
966	  if (typeof req.method !== 'string' || req.method === '') {
967	    storeFail(file, `${reqWhere}.method`, '必须是非空字符串');
968	  }
969	  if (typeof req.target !== 'string' || req.target === '') {
970	    storeFail(file, `${reqWhere}.target`, '必须是非空字符串');
971	  }
972	  if (typeof req.path !== 'string') {
973	    storeFail(file, `${reqWhere}.path`, '必须是字符串');
974	  }
975	  if ((req.target as string).split('?')[0] !== req.path) {
976	    storeFail(
977	      file,
978	      `${reqWhere}.path`,
979	      `与 target 去掉查询串后的路径不符：path=${JSON.stringify(req.path)}，target=${JSON.stringify(req.target)}`,
980	    );
981	  }
982	  if (!Array.isArray(req.rawHeaders) || req.rawHeaders.length % 2 !== 0) {
983	    storeFail(file, `${reqWhere}.rawHeaders`, '必须是成对（名称、值交替）的字符串数组');
984	  }
985	  for (let j = 0; j < req.rawHeaders.length; j += 1) {
986	    if (typeof req.rawHeaders[j] !== 'string') {
987	      storeFail(file, `${reqWhere}.rawHeaders[${j}]`, '必须是字符串');
988	    }
989	  }
990	  for (let j = 0; j + 1 < req.rawHeaders.length; j += 2) {
991	    validateStoredHeader(req.rawHeaders[j], req.rawHeaders[j + 1], file, `${reqWhere}.rawHeaders[${j}]`);
992	  }
993	  if (!Number.isInteger(req.bodyBytes) || (req.bodyBytes as number) < 0) {
994	    storeFail(file, `${reqWhere}.bodyBytes`, `必须是非负整数，收到 ${JSON.stringify(req.bodyBytes)}`);
995	  }
996	  const bodyWhere = `${reqWhere}.body`;
997	  if (!isPlainObject(req.body)) {
998	    storeFail(file, bodyWhere, '必须是对象（含 encoding 与 content）');
999	  }
1000	  const body = req.body as Record<string, unknown>;
1001	  if (body.encoding !== 'utf-8' && body.encoding !== 'base64') {
1002	    storeFail(file, `${bodyWhere}.encoding`, `必须是 "utf-8" 或 "base64"，收到 ${JSON.stringify(body.encoding)}`);
1003	  }
1004	  if (typeof body.content !== 'string') {
1005	    storeFail(file, `${bodyWhere}.content`, '必须是字符串');
1006	  }
1007	  let restoredBytes: Buffer;
1008	  if (body.encoding === 'utf-8') {
1009	    if (hasLoneSurrogate(body.content as string)) {
1010	      storeFail(file, `${bodyWhere}.content`, '含孤立代理项，无法无损还原原始字节');
1011	    }
1012	    restoredBytes = Buffer.from(body.content as string, 'utf8');
1013	  } else {
1014	    if (!BASE64_RE.test(body.content as string)) {
1015	      storeFail(file, `${bodyWhere}.content`, '不是合法的 base64 编码');
1016	    }
1017	    restoredBytes = Buffer.from(body.content as string, 'base64');
1018	  }
1019	  if (restoredBytes.byteLength !== (req.bodyBytes as number)) {
1020	    storeFail(
1021	      file,
1022	      bodyWhere,
1023	      `还原为 ${restoredBytes.byteLength} 字节，与 bodyBytes=${req.bodyBytes as number} 不符`,
1024	    );
1025	  }
