function requestsUsageNote(): string {
  const storage =
    requestStoreFile === ''
      ? '默认仅保存在本次服务进程内存中，进程退出即消失'
      : `已持久化到本地记录文件 ${requestStoreFile}，服务重启后仍可查询并用于 verify/replay`;
  return (
    `contractlab 请求记录（${storage}）：` +
    'GET /__contractlab/requests 查询一致快照（不推进序列，可保存后交给 verify、replay）；' +
    'POST /__contractlab/requests/clear 清空当时全部记录（持久模式仅移除记录、保留编号进度；不取消响应、不改配置/版本/序列）。' +
    'delivery=pending 表示计划响应待发送，sent 表示服务器已完成写出（不代表客户端已收到），' +
    'interrupted 表示写出完成前连接断开、发送失败，或重启恢复时上次未确认完成（不代表客户端未收到）。'
  );
}

async function handleAdmin(method: string, pathname: string, res: http.ServerResponse): Promise<void> {
  if (pathname === HEALTH_PATH) {
    if (method === 'GET') {
      sendJson(res, 200, { status: 'ok', version: activeState.version }, activeState.version);
    } else {
      sendNotFound(res);
    }
    return;
  }

  if (pathname === RELOAD_PATH) {
    if (method === 'POST') {
      const result = await triggerReload();
      sendJson(res, 200, result, result.version);
    } else {
      sendNotFound(res);
    }
    return;
  }

  if (pathname === REQUESTS_PATH) {
    if (method === 'GET') {
      const records = requestLog.snapshot();
      sendJson(
        res,
        200,
        { note: requestsUsageNote(), count: records.length, records },
        activeState.version,
      );
    } else {
      sendNotFound(res);
    }
    return;
  }

  if (pathname === REQUESTS_CLEAR_PATH) {
    if (method === 'POST') {
      try {
        // 只有保存删除结果后才返回成功
        const removed = await requestLog.clear();
        sendJson(
          res,
          200,
          { ok: true, removed, note: requestsUsageNote() },
          activeState.version,
        );
      } catch (e) {
        // 清空未成功保存：不得报成功（连接随之被关闭）；按运行中保存失败致命关闭
        handleStoreFailure(e);
      }
    } else {
      sendNotFound(res);
    }
    return;
  }

  // 管理范围内的未知路径：仍是管理请求，不记录、不消费
  sendNotFound(res);
}

