99	async function waitFor<T>(fn: () => Promise<T | null> | (T | null), timeoutMs = 4000, label = 'condition'): Promise<T> {
100	  const deadline = Date.now() + timeoutMs;
101	  let lastErr: unknown;
102	  for (;;) {
103	    try {
104	      const v = await fn();
105	      if (v !== null && v !== undefined) {
106	        return v as T;
107	      }
108	    } catch (e) {
109	      lastErr = e;
110	    }
111	    if (Date.now() > deadline) {
112	      throw new Error(`等待超时：${label}${lastErr ? `（${String(lastErr)}）` : ''}`);
113	    }
114	    await sleep(20);
115	  }
116	}
