231	// 场景中统一使用的可辨认成功响应：状态码与正文都足够独特，
232	// 不会与 400 校验拒绝或 404 接口缺失混淆。
233	export const SCENE_STATUS = 299;
234	export const SCENE_BODY = 'contractlab-scene-success';
235	
