239	
240	// ---------------------------------------------------------------------------
241	// 独立参考实现：按 README 记录的规则语义判断“规则是否接受某 JSON 值”
242	// ---------------------------------------------------------------------------
243	
244	export interface RuleJson {
245	  readonly type: string;
246	  readonly nullable?: boolean;
247	  readonly enum?: readonly unknown[];
248	  readonly fields?: { readonly [name: string]: RuleJson & { readonly required?: boolean } };
249	  readonly additionalProperties?: boolean;
250	  readonly items?: RuleJson;
251	  readonly required?: boolean;
252	}
253	
254	function isPlainJsonObject(value: unknown): value is Record<string, unknown> {
255	  return typeof value === 'object' && value !== null && !Array.isArray(value);
256	}
257	
258	// 标量类型的取值是否通过枚举候选（数字按数值相等，0 与 -0 等价，不做类型转换）
259	function enumAccepts(rule: RuleJson, value: unknown): boolean {
260	  return rule.enum === undefined || rule.enum.some((candidate) => candidate === value);
261	}
262	
263	export function accepts(rule: RuleJson, value: unknown): boolean {
264	  // nullable:true 在原接受集合上加入 null；null 被接受时不产生子节点差异；
265	  // 有枚举时可空不越过枚举：null 仍须列入候选才被接受
266	  if (value === null && rule.nullable === true) {
267	    return enumAccepts(rule, null);
268	  }
269	  switch (rule.type) {
270	    case 'string':
271	      return typeof value === 'string' && enumAccepts(rule, value);
272	    case 'boolean':
273	      return typeof value === 'boolean' && enumAccepts(rule, value);
274	    case 'null':
275	      return value === null;
276	    case 'number':
277	      return typeof value === 'number' && Number.isFinite(value) && enumAccepts(rule, value);
278	    case 'integer':
279	      return typeof value === 'number' && Number.isInteger(value) && enumAccepts(rule, value);
280	    case 'array':
281	      return Array.isArray(value) && value.every((item) => accepts(rule.items as RuleJson, item));
282	    case 'object': {
283	      if (!isPlainJsonObject(value)) {
284	        return false;
285	      }
286	      const fields = rule.fields ?? {};
287	      for (const [name, fieldRule] of Object.entries(fields)) {
288	        const has = Object.prototype.hasOwnProperty.call(value, name);
289	        if (!has) {
290	          if (fieldRule.required === true) {
291	            return false;
292	          }
293	        } else if (!accepts(fieldRule, value[name])) {
294	          return false;
295	        }
296	      }
297	      if (rule.additionalProperties !== true) {
298	        for (const key of Object.keys(value)) {
299	          if (!Object.prototype.hasOwnProperty.call(fields, key)) {
300	            return false;
301	          }
302	        }
303	      }
304	      return true;
305	    }
306	    default:
307	      throw new Error(`参考实现遇到未知规则类型: ${JSON.stringify(rule.type)}`);
308	  }
309	}
310	
311	// ---------------------------------------------------------------------------
312	// 有限代表值域
313	// ---------------------------------------------------------------------------
314	//
315	// 设计目标：对本测试矩阵中的每一对（旧规则, 新规则），只要二者接受的 JSON
316	// 值集合不同，域中就存在一个见证值。为此域必须区分：
317	// - 整数与非整数（0/1 与 0.5）：区分 integer 与 number 的双向变化；
318	// - 字段缺失与 null（删除变体 与 显式 null）：区分“必填缺失”与“类型为 null”；
319	// - 空数组与非空数组（[] 与 [v]）：元素规则收紧在空数组上不可见；
320	// - 已声明字段与未声明额外字段（zz_extra）：区分 additionalProperties 两种策略；
321	// - 对象与数组的嵌套（递归到 MAX_DEPTH 层）。
322	//
323	// 构造方式（对每层对象规则）：
324	// - 标量代表值全集；
325	// - 空数组，以及元素代表值构成的单元素数组（若任一规则声明了数组元素规则，
326	//   元素域递归生成，否则用标量）；
327	// - 空对象、仅含额外字段的对象；
328	// - “基对象”：两规则声明字段的并集各取一个双方（退化为旧方）都接受的值，
329	//   再叠加额外字段；随后对每个字段做“删除”与“逐代表值替换”变体。
330	// 这样，新增必填字段由删除变体见证、字段类型收紧由替换变体见证、
331	// additionalProperties 收紧由叠加额外字段的对象见证、嵌套收紧由递归域见证。
332	//
333	// 注意：这只是针对本矩阵所测规则对的充分见证域，不构成对任意递归规则
334	// 包含关系的证明；矩阵中每条用例的期望都来自该域的穷举结果。
335	
336	const MAX_DEPTH = 2;
337	
338	// 标量代表值：覆盖 string（含空串）、整数、非整数、boolean、null
339	const SCALAR_REPS: readonly unknown[] = ['txt', '', 0, 1, 0.5, true, false, null];
340	
341	type FieldMap = { readonly [name: string]: RuleJson & { readonly required?: boolean } };
342	
343	function objectFields(rule: RuleJson | undefined): FieldMap {
344	  return rule !== undefined && rule.type === 'object' ? (rule.fields ?? {}) : {};
345	}
346	
347	function pickBase(
348	  subDomain: readonly unknown[],
349	  oldField: RuleJson | undefined,
350	  newField: RuleJson | undefined,
351	): unknown {
352	  const ok = (rule: RuleJson | undefined, v: unknown): boolean =>
353	    rule === undefined || accepts(rule, v);
354	  // 优先选双方规则都接受的值（基对象尽量是“好公民”），退化为旧规则接受，再退化为首元素
355	  return (
356	    subDomain.find((v) => ok(oldField, v) && ok(newField, v)) ??
357	    subDomain.find((v) => ok(oldField, v)) ??
358	    subDomain[0]
359	  );
360	}
361	
362	export function domainFor(
363	  oldRule: RuleJson | undefined,
364	  newRule: RuleJson | undefined,
365	  depth = 0,
366	): unknown[] {
367	  const values: unknown[] = [...SCALAR_REPS];
368	  if (depth >= MAX_DEPTH) {
369	    values.push([], {});
370	    return values;
371	  }
372	
373	  // 数组：空数组 + 元素代表值的单元素数组
374	  values.push([]);
375	  const itemOld = oldRule !== undefined && oldRule.type === 'array' ? oldRule.items : undefined;
376	  const itemNew = newRule !== undefined && newRule.type === 'array' ? newRule.items : undefined;
377	  const itemDomain =
378	    itemOld !== undefined || itemNew !== undefined
379	      ? domainFor(itemOld, itemNew, depth + 1)
380	      : SCALAR_REPS;
381	  for (const v of itemDomain) {
382	    values.push([v]);
383	  }
384	
385	  // 对象：空对象、额外字段对象、基对象及其删除/替换变体
386	  const fieldsOld = objectFields(oldRule);
387	  const fieldsNew = objectFields(newRule);
388	  const names = [...new Set([...Object.keys(fieldsOld), ...Object.keys(fieldsNew)])];
389	  let extra = 'zz_extra';
390	  while (names.includes(extra)) {
391	    extra = `${extra}_x`;
392	  }
393	  values.push({}, { [extra]: 0 }, { [extra]: 'txt' });
394	
395	  if (names.length > 0) {
396	    const subDomains = new Map<string, unknown[]>();
397	    const base: Record<string, unknown> = {};
398	    for (const name of names) {
399	      const sd = domainFor(fieldsOld[name], fieldsNew[name], depth + 1);
400	      subDomains.set(name, sd);
401	      base[name] = pickBase(sd, fieldsOld[name], fieldsNew[name]);
402	    }
403	    values.push(base, { ...base, [extra]: 0 }, { ...base, [extra]: 'txt' });
404	    for (const name of names) {
405	      const deleted = { ...base };
406	      delete deleted[name];
407	      values.push(deleted);
408	      for (const v of subDomains.get(name) as unknown[]) {
409	        if (!Object.is(v, base[name])) {
410	          values.push({ ...base, [name]: v });
411	        }
412	      }
413	    }
414	  }
415	
416	  return values;
417	}
